import os, json, uuid, hashlib, socket, ipaddress, io, zipfile
from datetime import datetime, timezone
from pathlib import Path
from fastapi import FastAPI, Request, HTTPException, Depends
from fastapi.responses import JSONResponse, Response
from pydantic import BaseModel, Field
from sqlalchemy import select
from .models import Base, Record, Audit, Session, engine
from .security import identity, csrf, password_hash, verify, token
app=FastAPI(title="DUDOS portable API",version="1.0.0")
class Login(BaseModel):
    email:str=Field(max_length=200)
    password:str=Field(min_length=1,max_length=200)
class Save(BaseModel):
    data:dict
    revision:int=Field(ge=0)
def log(s,user,action,rid,detail):
    s.add(Audit(id=str(uuid.uuid4()),actor=user,action=action,record_id=rid,detail=json.dumps(detail)))
@app.middleware("http")
async def limits(request,call_next):
    try:
        if int(request.headers.get("content-length","0"))>1000000:
            return JSONResponse({"detail":"Request too large"},413)
    except ValueError:
        return JSONResponse({"detail":"Invalid content length"},400)
    if request.method in ["POST","PUT","PATCH","DELETE"]:
        chunks=[]; size=0
        async for chunk in request.stream():
            size+=len(chunk)
            if size>1000000:return JSONResponse({"detail":"Request too large"},413)
            chunks.append(chunk)
        request._body=b"".join(chunks)
    if request.method in ["POST","PUT","PATCH","DELETE"]:
        try: csrf(request)
        except HTTPException as e: return JSONResponse({"detail":e.detail},e.status_code)
    response=await call_next(request)
    response.headers["X-Content-Type-Options"]="nosniff"
    response.headers["Cache-Control"]="no-store"
    return response
@app.get("/api/health")
def health():
    with Session() as s: s.execute(select(Record.id).limit(1))
    return {"status":"ok","version":"1.0.0","database":"connected","ai":bool(os.getenv("OLLAMA_URL"))}
@app.post("/api/login")
def login(b:Login):
    with Session() as s:
        r=s.get(Record,"admin")
        if not r or b.email.lower()!=json.loads(r.data)["email"] or not verify(b.password,json.loads(r.data)["hash"]):
            raise HTTPException(401,"Invalid sign-in details")
        response=JSONResponse({"user":"admin"})
        response.set_cookie("dudos_session",token("admin"),httponly=True,secure=os.getenv("COOKIE_SECURE","true")=="true",samesite="strict",max_age=28800,path="/")
        log(s,"admin","login","admin",{});s.commit()
        return response
@app.post("/api/logout")
def logout():
    r=JSONResponse({"ok":True});r.delete_cookie("dudos_session");return r
@app.get("/api/me")
def me(user=Depends(identity)): return {"user":user}
@app.get("/api/projects")
def projects(user=Depends(identity)):
    with Session() as s:
        return [{"id":r.id,"data":json.loads(r.data),"revision":r.revision} for r in s.scalars(select(Record).where(Record.owner==user,Record.kind=="project"))]
@app.put("/api/projects/{rid}")
def save(rid:str,b:Save,user=Depends(identity)):
    if len(rid)>80 or len(json.dumps(b.data))>300000: raise HTTPException(400,"Project too large")
    with Session() as s:
        r=s.scalar(select(Record).where(Record.id==rid).with_for_update())
        if r and (r.owner!=user or r.kind!="project"): raise HTTPException(404,"Project not found")
        if r and r.revision!=b.revision: raise HTTPException(409,"A newer revision exists; reload before saving")
        if not r and b.revision!=0: raise HTTPException(409,"Project not found at requested revision")
        if not r:r=Record(id=rid,owner=user,kind="project",data="{}",revision=0);s.add(r)
        r.data=json.dumps(b.data);r.revision+=1;r.updated=datetime.now(timezone.utc)
        log(s,user,"project.saved",rid,{"revision":r.revision,"sha256":hashlib.sha256(r.data.encode()).hexdigest()});s.commit()
        return {"id":rid,"revision":r.revision}
@app.get("/api/audit")
def audit(user=Depends(identity)):
    with Session() as s:return [{"action":r.action,"record_id":r.record_id,"detail":json.loads(r.detail),"created":r.created.isoformat()} for r in s.scalars(select(Audit).where(Audit.actor==user).order_by(Audit.created.desc()).limit(200))]
@app.get("/api/dns")
def dns(domain:str,user=Depends(identity)):
    import re
    if not re.fullmatch(r"(?=.{1,253}$)(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}",domain): raise HTTPException(400,"Invalid domain")
    try: addresses=sorted({x[4][0] for x in socket.getaddrinfo(domain,None)})
    except socket.gaierror: return {"resolved":False,"addresses":[],"ownership_verified":False}
    return {"resolved":True,"addresses":addresses,"ownership_verified":False,"note":"Resolution does not prove ownership or target-server configuration"}
@app.post("/api/assist")
async def assist(b:dict,user=Depends(identity)):
    import httpx
    question=str(b.get("question",""))[:3000]
    base=os.getenv("OLLAMA_URL","")
    if not base:return {"mode":"rules","text":"Confirm your audience, editable pages and service workflow. React + PostgreSQL suits a custom portal; WordPress suits an editorial site. Review integration rights before activation."}
    try:
        async with httpx.AsyncClient(timeout=60) as client:
            r=await client.post(base.rstrip("/")+"/api/generate",json={"model":os.getenv("OLLAMA_MODEL","llama3.2"),"prompt":"You are a website planning assistant. Do not claim to run tools or approve actions. Give concise suggestions. User context: "+question,"stream":False});r.raise_for_status()
            return {"mode":"local_ai","text":r.json()["response"][:12000]}
    except Exception:raise HTTPException(503,"Local model is unavailable; your project has not changed")
# CMS endpoints are shared by generated React/Next.js sites.
@app.get("/api/pages")
def pages():
    with Session() as s:return [json.loads(r.data) for r in s.scalars(select(Record).where(Record.kind=="page"))]
@app.put("/api/pages/{slug}")
def edit_page(slug:str,b:Save,user=Depends(identity)):
    import re
    if not re.fullmatch(r"[a-z0-9-]{1,70}",slug):raise HTTPException(400,"Invalid page slug")
    if len(json.dumps(b.data))>100000:raise HTTPException(400,"Page too large")
    with Session() as s:
        r=s.scalar(select(Record).where(Record.id=="page:"+slug).with_for_update())
        if r and r.revision!=b.revision:raise HTTPException(409,"Reload the latest page before saving")
        if not r and b.revision!=0:raise HTTPException(409,"Revision conflict")
        if not r:r=Record(id="page:"+slug,owner=user,kind="page",data="{}",revision=0);s.add(r)
        r.revision+=1;r.data=json.dumps({"slug":slug,"title":str(b.data.get("title",""))[:200],"body":str(b.data.get("body",""))[:50000],"revision":r.revision})
        log(s,user,"page.saved",r.id,{"revision":r.revision});s.commit();return json.loads(r.data)
@app.post("/api/contact")
def contact(b:dict):
    if b.get("website"): return {"received":True}
    import re
    if not re.fullmatch(r"[^\s@]+@[^\s@]+\.[^\s@]+",str(b.get("email",""))) or not str(b.get("message","")).strip() or len(str(b))>10000:raise HTTPException(400,"Provide an email and a short message")
    with Session() as s:
        rid=str(uuid.uuid4());s.add(Record(id=rid,owner="admin",kind="enquiry",data=json.dumps({k:str(b.get(k,""))[:3000] for k in ["name","email","message"]})));s.commit()
    return {"received":True,"reference":rid}
@app.get("/api/enquiries")
def enquiries(user=Depends(identity)):
    with Session() as s:return [{"id":r.id,"data":json.loads(r.data)} for r in s.scalars(select(Record).where(Record.kind=="enquiry",Record.owner==user))]

