import os, secrets, hashlib, hmac, time, json, base64
from fastapi import HTTPException, Request
SECRET=os.environ["SESSION_SECRET"]
if len(SECRET)<32: raise RuntimeError("SESSION_SECRET must have at least 32 characters")
def password_hash(password, salt=None):
    salt=salt or secrets.token_hex(16)
    return salt+":"+hashlib.scrypt(password.encode(),salt=salt.encode(),n=16384,r=8,p=1).hex()
def verify(password, stored):
    return hmac.compare_digest(password_hash(password,stored.split(":")[0]),stored)
def token(user):
    payload=base64.urlsafe_b64encode(json.dumps({"user":user,"exp":int(time.time())+28800}).encode()).decode()
    return payload+"."+hmac.new(SECRET.encode(),payload.encode(),hashlib.sha256).hexdigest()
def identity(request:Request):
    try:
        payload,sig=request.cookies.get("dudos_session","").split(".")
        expected=hmac.new(SECRET.encode(),payload.encode(),hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig,expected): raise ValueError()
        data=json.loads(base64.urlsafe_b64decode(payload))
        if data["exp"]<time.time(): raise ValueError()
        return data["user"]
    except Exception: raise HTTPException(401,"Sign in to continue")
def csrf(request:Request):
    origin=request.headers.get("origin","")
    if origin != os.environ.get("PUBLIC_ORIGIN","http://localhost:8080"):
        raise HTTPException(403,"Request origin not accepted")

