'use client';
import React,{useState,useEffect}from'react';
const config=__CONFIG__;
export default function Site(){
 const[pages,setPages]=useState<any[]>([]),[active,setActive]=useState('home'),[admin,setAdmin]=useState(false),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[message,setMessage]=useState(''),[enquiries,setEnquiries]=useState<any[]>([]);
 const load=()=>fetch('/api/pages').then(r=>r.json()).then((data:any)=>setPages(data)).catch(()=>setMessage('Unable to load pages. Check the API.'));
 useEffect(()=>{load();const update=()=>setActive(location.hash.slice(1)||'home');update();window.addEventListener('hashchange',update);return()=>window.removeEventListener('hashchange',update)},[]);
 const request=async(path:string,data:any,method='POST')=>{const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const b:any=await r.json();if(!r.ok)throw Error(b.detail||'Request failed');return b};
 const page=pages.find(p=>p.slug===active)||pages[0];
 return <><style dangerouslySetInnerHTML={{__html:config.heroCss}}/><header><a href="#home"><strong>{config.name}</strong></a><nav>{pages.map(p=><a key={p.slug} href={'#'+p.slug}>{p.title}</a>)}<a href="#cms">CMS</a></nav></header><main>{message&&<p role="status">{message}</p>}{active==='cms'?<><h1>Manage your website</h1>{!admin?<form onSubmit={async e=>{e.preventDefault();try{await request('login',{email,password});setAdmin(true);setPassword('');setMessage('Signed in')}catch(e:any){setMessage(e.message)}}}><label>Email<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<input type="password" required value={password} onChange={e=>setPassword(e.target.value)}/></label><button>Sign in</button></form>:<><button onClick={async()=>{await request('logout',{});setAdmin(false)}}>Sign out</button>{pages.map((p,i)=><form key={p.slug} onSubmit={async e=>{e.preventDefault();try{await request('pages/'+p.slug,{data:p,revision:p.revision},'PUT');await load();setMessage('Page saved')}catch(e:any){setMessage(e.message)}}}><label>Page title<input value={p.title} onChange={e=>setPages(ps=>ps.map((x,j)=>i===j?{...x,title:e.target.value}:x))}/></label><label>Page content<textarea rows={6} value={p.body} onChange={e=>setPages(ps=>ps.map((x,j)=>i===j?{...x,body:e.target.value}:x))}/></label><button>Save {p.slug}</button></form>)}<button onClick={async()=>{const r=await fetch('/api/enquiries');if(r.ok)setEnquiries(await r.json());else setMessage('Sign in again')}}>Load enquiries</button>{enquiries.map(x=><article key={x.id}>{x.data.name} · {x.data.email}<p>{x.data.message}</p></article>)}</> }</>:active==='home'?<div dangerouslySetInnerHTML={{__html:config.heroHtml}}/>:<><p className="eyebrow">{config.category}</p><h1>{page?.title||config.name}</h1><p className="body">{page?.body||'Loading content…'}</p>{active==='contact'&&<form onSubmit={async e=>{e.preventDefault();const f=e.currentTarget;const d=Object.fromEntries(new FormData(f));try{await request('contact',d);setMessage('Thank you. Your enquiry has been saved.');f.reset()}catch(e:any){setMessage(e.message)}}}><label>Name<input name="name" required/></label><label>Email<input name="email" type="email" required/></label><label>Message<textarea name="message" required maxLength={3000}/></label><input name="website" tabIndex={-1} autoComplete="off" style={{display:'none'}}/><button>Send enquiry</button></form>}{config.video&&<p><a href={config.video} rel="noreferrer">Watch our introduction</a></p>}</>}</main><footer>{config.name} · {config.domain}<div>{Object.entries(config.social||{}).filter(([k,v])=>v).map(([k,v])=><a key={k} href={String(v)} rel="noreferrer">{k}</a>)}</div></footer></>}

