import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

const config = __CONFIG__;

interface Page { slug: string; title: string; body: string; revision: number }

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  template: `
<style [innerHTML]="heroCss"></style>
<header>
  <a href="#home"><strong>{{ config.name }}</strong></a>
  <nav>
    <a *ngFor="let p of pages" [href]="'#' + p.slug">{{ p.title }}</a>
    <a href="#cms">CMS</a>
  </nav>
</header>
<main>
  <p role="status" *ngIf="message">{{ message }}</p>

  <ng-container *ngIf="active === 'cms'; else notCms">
    <h1>Manage your website</h1>
    <form *ngIf="!admin" (submit)="login($event)">
      <label>Email<input type="email" name="email" required [value]="email" (input)="email = $any($event.target).value"/></label>
      <label>Password<input type="password" name="password" required [value]="password" (input)="password = $any($event.target).value"/></label>
      <button>Sign in</button>
    </form>
    <ng-container *ngIf="admin">
      <button (click)="logout()">Sign out</button>
      <form *ngFor="let p of pages; let i = index" (submit)="savePage($event, p)">
        <label>Page title<input [value]="p.title" (input)="p.title = $any($event.target).value"/></label>
        <label>Page content<textarea rows="6" [value]="p.body" (input)="p.body = $any($event.target).value"></textarea></label>
        <button>Save {{ p.slug }}</button>
      </form>
      <button (click)="loadEnquiries()">Load enquiries</button>
      <article *ngFor="let x of enquiries">
        {{ x.data.name }} &middot; {{ x.data.email }}
        <p>{{ x.data.message }}</p>
      </article>
    </ng-container>
  </ng-container>

  <ng-template #notCms>
    <div *ngIf="active === 'home'; else innerPage" [innerHTML]="heroHtml"></div>
    <ng-template #innerPage>
      <p class="eyebrow">{{ config.category }}</p>
      <h1>{{ page?.title || config.name }}</h1>
      <p class="body">{{ page?.body || 'Loading content…' }}</p>
      <form *ngIf="active === 'contact'" (submit)="sendContact($event)">
        <label>Name<input name="name" required/></label>
        <label>Email<input name="email" type="email" required/></label>
        <label>Message<textarea name="message" required maxlength="3000"></textarea></label>
        <input name="website" tabindex="-1" autocomplete="off" style="display:none"/>
        <button>Send enquiry</button>
      </form>
      <p *ngIf="config.video"><a [href]="config.video" rel="noreferrer">Watch our introduction</a></p>
    </ng-template>
  </ng-template>
</main>
<footer>
  {{ config.name }} &middot; {{ config.domain }}
  <div>
    <a *ngFor="let kv of socialEntries" [href]="kv[1]" rel="noreferrer">{{ kv[0] }}</a>
  </div>
</footer>
`,
})
export class AppComponent implements OnInit, OnDestroy {
  config = config;
  pages: Page[] = [];
  active = 'home';
  admin = false;
  email = '';
  password = '';
  message = '';
  enquiries: { id: string; data: any }[] = [];
  heroHtml: SafeHtml;
  heroCss: SafeHtml;
  socialEntries: [string, string][] = Object.entries(config.social || {}).filter(([, v]) => v) as [string, string][];
  private onHashChange = () => { this.active = location.hash.slice(1) || 'home' };

  constructor(private sanitizer: DomSanitizer) {
    this.heroHtml = this.sanitizer.bypassSecurityTrustHtml(config.heroHtml);
    this.heroCss = this.sanitizer.bypassSecurityTrustHtml(config.heroCss);
  }

  get page(): Page | undefined {
    return this.pages.find((p) => p.slug === this.active) || this.pages[0];
  }

  ngOnInit() {
    this.load();
    this.onHashChange();
    window.addEventListener('hashchange', this.onHashChange);
  }

  ngOnDestroy() {
    window.removeEventListener('hashchange', this.onHashChange);
  }

  load() {
    fetch('/api/pages')
      .then((r) => r.json())
      .then((data: Page[]) => (this.pages = data))
      .catch(() => (this.message = 'Unable to load pages. Check the API.'));
  }

  private async request(path: string, data: any, method = 'POST') {
    const r = await fetch('/api/' + path, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    const b: any = await r.json();
    if (!r.ok) throw Error(b.detail || 'Request failed');
    return b;
  }

  async login(e: Event) {
    e.preventDefault();
    try {
      await this.request('login', { email: this.email, password: this.password });
      this.admin = true;
      this.password = '';
      this.message = 'Signed in';
    } catch (err: any) {
      this.message = err.message;
    }
  }

  async logout() {
    await this.request('logout', {});
    this.admin = false;
  }

  async savePage(e: Event, p: Page) {
    e.preventDefault();
    try {
      await this.request('pages/' + p.slug, { data: p, revision: p.revision }, 'PUT');
      this.load();
      this.message = 'Page saved';
    } catch (err: any) {
      this.message = err.message;
    }
  }

  async loadEnquiries() {
    const r = await fetch('/api/enquiries');
    if (r.ok) this.enquiries = await r.json();
    else this.message = 'Sign in again';
  }

  async sendContact(e: Event) {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const data = Object.fromEntries(new FormData(form) as any);
    try {
      await this.request('contact', data);
      this.message = 'Thank you. Your enquiry has been saved.';
      form.reset();
    } catch (err: any) {
      this.message = err.message;
    }
  }
}

